// LoggerOpenFile sends the library's log to a file
//
// Process-wide, not per handle. Every rank writing to one path on a
// shared filesystem interleaves its output with the others.
//
//   - logFile: path to open; copied by the library
//
// Wraps cusolverMpLoggerOpenFile.
func LoggerOpenFile(logFile string) error {
	if err := checkLibSym("cusolverMpLoggerOpenFile"); err != nil {
		return err
	}
	logFile_cstr := append([]byte(logFile), 0)
	return toError(fnLoggerOpenFile(&logFile_cstr[0]), "cusolverMpLoggerOpenFile")
}

